(() => {
 'use strict';
 const modules=window.CAMPUS_MODULES, tables=window.CAMPUS_DATA;
 const STORAGE='planning-lab-havi-v1';
 const icons={
  grid:'<rect x="3" y="3" width="7" height="7" rx="1.4"/><rect x="14" y="3" width="7" height="7" rx="1.4"/><rect x="3" y="14" width="7" height="7" rx="1.4"/><rect x="14" y="14" width="7" height="7" rx="1.4"/>',
  book:'<path d="M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4zM13 7a3 3 0 0 1 3-3h5v15h-4a4 4 0 0 0-4 2"/>',
  code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-2-15-4 18"/>',
  data:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v7c0 4 16 4 16 0V5M4 12v7c0 4 16 4 16 0v-7"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  check:'<path d="m5 12 4 4L19 6"/>',
  arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',
  chart:'<path d="M4 3v17h17M8 15v-4m5 4V6m5 9V9"/>',
  file:'<path d="M14 3H5v18h14V8zM14 3v5h5M8 12h8m-8 4h6"/>',
  down:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
  play:'<path d="m8 4 12 8-12 8z"/>',
  bulb:'<path d="M9 18h6m-6 3h6M8 14a7 7 0 1 1 8 0c-1 1-1 2-1 2H9s0-1-1-2z"/>',
  link:'<path d="m9 15 6-6m-8 8-1 1a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0m4-1 1-1a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0"/>',
 };
 const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.book}</svg>`;
 const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
 const emptyState=()=>({version:1,route:'sprint',lessons:{},quizzes:{},labs:{},drafts:{},notes:{},hints:{},assisted:{},readingSteps:{},guided:{},mock:{remaining:1800,running:false},updated:null});
 let state=emptyState(),storageBlocked=false;
 try{const saved=JSON.parse(localStorage.getItem(STORAGE));if(saved?.version===1)state={...state,...saved,mock:{...state.mock,...saved.mock,running:false}};}catch(e){storageBlocked=true;}
 let page='home',selectedModule=modules[0].id, outputs={},solutions={},quizFeedback={},worker,workerReady,seq=0,pending=new Map();
 let selectedTable='daily_plan',sandboxDraft="SELECT *\nFROM daily_plan\nLIMIT 10;",lastSandbox=null;
 let lessonSections={},walkSteps={},walkOutputs={},guidedFeedback={};
 const app=document.getElementById('app');
 const routeFast=()=>state.route==='sprint';
 const visibleLabs=m=>m.labs.filter(l=>!routeFast()||l.fast);
 const moduleUnits=m=>2+visibleLabs(m).length;
 const moduleDone=m=>(state.lessons[m.id]?1:0)+(state.quizzes[m.id]?1:0)+visibleLabs(m).filter(l=>state.labs[l.id]?.passed).length;
 const percent=m=>Math.round(100*moduleDone(m)/moduleUnits(m));
 const totalUnits=()=>modules.reduce((n,m)=>n+moduleUnits(m),0);
 const doneUnits=()=>modules.reduce((n,m)=>n+moduleDone(m),0);
 const overall=()=>Math.round(100*doneUnits()/totalUnits());
 const minutes=()=>modules.reduce((n,m)=>n+m[routeFast()?'fast':'full'],0);
 const nextModule=()=>modules.find(m=>moduleDone(m)<moduleUnits(m))||modules[modules.length-1];
 const allLabs=modules.flatMap(m=>m.labs);
 const findLab=id=>allLabs.find(l=>l.id===id);
 const isSql=l=>!l.type;
 const sourceLink=(label,url)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
 function save(){state.updated=new Date().toISOString();try{localStorage.setItem(STORAGE,JSON.stringify(state));}catch(e){storageBlocked=true;}}
 function toast(text){const el=document.getElementById('toast');el.textContent=text;el.style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>el.style.display='none',3400);}
 function download(name,content,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
 function csv(t){return t.columns.join(',')+'\r\n'+t.rows.map(row=>row.map(x=>x===null?'':typeof x==='number'?x:'"'+x.replaceAll('"','""')+'"').join(',')).join('\r\n');}
 function initWorker(){
  if(worker)worker.terminate();
  worker=new Worker('sql-worker.js');
  workerReady=new Promise((resolve,reject)=>{
   const id=++seq;
   pending.set(id,{resolve:()=>resolve(),reject});
   worker.onmessage=({data})=>{const p=pending.get(data.id);if(!p)return;pending.delete(data.id);data.error?p.reject(new Error(data.error)):p.resolve(data);};
   worker.onerror=()=>{reject(new Error('The SQL engine could not load. Reload the page, or check whether your browser allows WebAssembly workers.'));};
   worker.postMessage({id,type:'init',tables});
  });
  workerReady.catch(()=>{});
 }
 async function runSql(sql,expected,ordered){
  await workerReady;
  return new Promise((resolve,reject)=>{
   const id=++seq;
   const timer=setTimeout(()=>{
    for(const p of pending.values())p.reject(new Error('Query exceeded 8 seconds. The SQL engine was restarted. Check for a missing join condition or an unbounded recursive query.'));
    pending.clear();initWorker();
   },8000);
   pending.set(id,{resolve:d=>{clearTimeout(timer);resolve(d);},reject:e=>{clearTimeout(timer);reject(e);}});
   worker.postMessage({id,type:'run',sql,expected,ordered});
  });
 }
 function tableHtml(result,max=100){if(!result)return '';if(!result.values.length)return '<div class="empty">The query returned 0 rows.</div>';return `<div class="tablewrap"><table><thead><tr>${result.columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${result.values.slice(0,max).map(row=>`<tr>${row.map(v=>`<td>${v===null?'<span class="muted">NULL</span>':esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${result.values.length>max?`<p class="subtle">Showing ${max} of ${result.values.length} rows. CSV export includes all rows.</p>`:''}`;}
 function formatMinutes(n){return n<60?`${n} min`:`${Math.floor(n/60)}h ${n%60?`${n%60}m`:''}`;}
 function moduleCard(m,i,compact=false){compact=compact===true;const p=percent(m),current=m.id===nextModule().id;return `<button class="modulecard ${p===100?'complete':current?'current':''}" data-module="${m.id}"><span class="module-num">${p===100?'✓':String(i+1).padStart(2,'0')}</span><span class="module-body"><h3>${esc(m.title)}</h3><p>${m[routeFast()?'fast':'full']} min${compact?'':` · ${visibleLabs(m).length} practice ${visibleLabs(m).length===1?'task':'tasks'} · ${p}% complete`}</p></span>${!compact?`<span class="pill ${m.kind==='Excel'?'blue':m.id==='mock'?'orange':''}">${esc(m.kind)}</span><span class="arrow">↗</span>`:''}</button>`;}
 function routeTabs(){return `<div class="route-tabs" role="group" aria-label="Study route"><button class="route-tab ${routeFast()?'active':''}" data-route="sprint">Core interview route · ~3h</button><button class="route-tab ${!routeFast()?'active':''}" data-route="full">Extra practice · ~7h total</button></div>`;}
 function render(){
  const nav=[['home','grid','Overview'],['path','book','Learning path'],['playground','code','SQL playground'],['data','data','Data desk'],['mock','clock','Interview rehearsal'],['reference','file','Quick reference'],['progress','chart','My progress'],['sources','link','Sources & scope']];
  const active=page==='lesson'?'path':page;
  app.innerHTML=`<div class="shell"><aside class="sidebar"><button class="brand" data-page="home"><span class="brandmark"><i></i><i></i><i></i><i></i></span>planning lab<span class="subtle">/</span></button><div class="navlabel">YOUR CAMPUS</div><nav class="sidenav" aria-label="Campus">${nav.map(([p,i,label])=>`<button class="navitem ${active===p?'active':''}" data-page="${p}">${icon(i)}${label}${p==='path'?'<small>10</small>':''}</button>`).join('')}</nav><div class="sidebarfoot"><div class="coursecard"><span class="eyebrow">YOUR INTERVIEW SPRINT</span><p><strong>HAVI · Planning Systems</strong><br>SQL, Excel & clear reasoning</p><div class="mini-progress"><span style="width:${overall()}%"></span></div><p style="margin-bottom:0">${overall()}% of ${routeFast()?'sprint':'full route'} complete</p></div><p class="footnote">${storageBlocked?'Browser storage unavailable. Export progress before leaving.':'Progress saves in this browser.'}<br>Use My progress to export a backup.</p></div></aside><div><header class="topbar"><div class="breadcrumb">Career campus <span>/</span> <span class="crumb">${esc(nav.find(n=>n[0]===active)?.[2]||'Learning path')}</span></div><div class="user"><span class="datechip">Wednesday interview · Nov 11</span><span>Randy McFarland</span><div class="avatar">RM</div></div></header><main class="main" id="main" tabindex="-1">${pageContent()}</main></div></div>`;
  bind();
 }
 function pageContent(){switch(page){case 'home':return home();case 'path':return path();case 'lesson':return lessonReader(modules.find(m=>m.id===selectedModule));case 'playground':return playground();case 'data':return dataPage();case 'mock':return lessonReader(modules.find(m=>m.id==='mock'));case 'reference':return reference();case 'progress':return progress();case 'sources':return sources();default:return home();}}
 function sectionTabs(m){const current=lessonSections[m.id]||'learn';return `<div class="lesson-sections" role="group" aria-label="Lesson stages">${[['learn','1','Understand'],['walk','2',m.walkthrough?'See it happen':'Guided example'],['practice','3','Try it yourself']].map(([id,n,label])=>`<button class="lesson-section ${current===id?'active':''}" data-lesson-section="${id}" data-owner="${m.id}" aria-pressed="${current===id}"><span>${n}</span>${label}</button>`).join('')}</div>`;}
 function lessonReader(m){
  const section=lessonSections[m.id]||'learn',isMock=m.id==='mock';
  let content;
  if(section==='learn'){
   const step=Math.min(state.readingSteps[m.id]||0,m.blocks.length-1),block=m.blocks[step];
   content=`<div class="reader-status"><span>Idea ${step+1} of ${m.blocks.length}</span><label>Jump to an idea <select id="reading-picker" aria-label="Choose a lesson idea" data-owner="${m.id}">${m.blocks.map((b,i)=>`<option value="${i}" ${i===step?'selected':''}>${i+1}. ${esc(b[0])}</option>`).join('')}</select></label></div><div class="reader-track" aria-hidden="true">${m.blocks.map((_,i)=>`<span class="${i<=step?'seen':''}"></span>`).join('')}</div><section class="concept reading-card"><div class="eyebrow">UNDERSTAND THE REASONING</div><h2>${esc(block[0])}</h2>${block[1]}</section><div class="reader-controls"><button class="btn light" data-read-step="${Math.max(0,step-1)}" data-owner="${m.id}" ${step===0?'disabled':''}>← Previous idea</button><span class="subtle">${step+1} / ${m.blocks.length}</span>${step<m.blocks.length-1?`<button class="btn" data-read-step="${step+1}" data-owner="${m.id}">Next idea ${icon('arrow')}</button>`:`<button class="btn" data-lesson-section="walk" data-owner="${m.id}">See a worked example ${icon('arrow')}</button>`}</div>${step===m.blocks.length-1?`<div class="panel"><label class="checkline"><input type="checkbox" data-read="${m.id}" ${state.lessons[m.id]?'checked':''}>I can explain the main ideas in this lesson in my own words.</label></div>`:''}`;
  }else if(section==='walk'){
   content=m.walkthrough?walkthrough(m):`<section class="concept"><h2>Connect the teaching to the exercise</h2><p>${esc(m.outcome)}</p><p>${m.kind==='Excel'?'Download the CSV files from Data desk and open them in Excel. Use the named tables described in the lesson. Predict whether you need a lookup, a conditional sum or a grouped summary before choosing a formula.':'Rehearse your thinking before moving to the tasks. First name the output grain, then the source, the filters or keys, and the validation check.'}</p></section>`;
   content+=guided(m)+`<div class="reader-controls"><button class="btn light" data-lesson-section="learn" data-owner="${m.id}">← Back to teaching</button><button class="btn" data-lesson-section="practice" data-owner="${m.id}">Try the exercises ${icon('arrow')}</button></div>`;
  }else{
   content=`${isMock?timerPanel():''}<div class="path-note"><strong>Practice sequence:</strong> answer the knowledge check, then work through the exercises below. If the syntax is unclear, return to <strong>See it happen</strong> and run the example first. Hints are available in every lab.</div>${quiz(m)}<div class="sectionhead"><h2>${isMock?'Practice assessment':'Your practice tasks'}</h2><button class="textbtn" data-page="data">Tables & Excel files ↗</button></div>${visibleLabs(m).map(activity).join('')}${visibleLabs(m).length===0?'<div class="path-note">This introductory module checks your understanding. The next module begins the coding exercises.</div>':''}<div class="panel"><label class="checkline"><input type="checkbox" data-read="${m.id}" ${state.lessons[m.id]?'checked':''}>I can explain the main ideas in this lesson in my own words.</label></div><div class="panel"><h3>My notes</h3><p>Write the operation, why you chose it, and the result you expect.</p><textarea class="notes" data-note="${m.id}" aria-label="My notes for ${esc(m.title)}" placeholder="For example: LEFT JOIN preserves my plan records. I check p.product_id IS NULL to identify missing master matches.">${esc(state.notes[m.id]||'')}</textarea></div><div class="toolbar"><button class="btn light" data-lesson-section="walk" data-owner="${m.id}">Review the worked example</button><span class="spacer"></span>${modules.indexOf(m)<modules.length-1?`<button class="btn" data-module="${modules[modules.indexOf(m)+1].id}">Next module ${icon('arrow')}</button>`:`<button class="btn" data-page="progress">Review my progress ${icon('arrow')}</button>`}</div>`;
  }
  return `<div class="lesson-layout"><aside class="course-menu"><div class="eyebrow">YOUR LEARNING ORDER</div>${modules.map((x,i)=>moduleCard(x,i,true)).join('')}</aside><article class="lesson"><div class="lesson-head"><div class="lesson-meta"><span class="pill ${m.kind==='Excel'?'blue':''}">${esc(m.kind)}</span><span class="muted" style="font-size:11px">Module ${String(modules.indexOf(m)+1).padStart(2,'0')} of 10 · ${m[routeFast()?'fast':'full']} min guide</span><span class="badge">${percent(m)}% complete</span></div><h1>${esc(m.title)}</h1><p>${esc(m.subtitle)}</p><div class="lesson-outcome"><strong>By the end:</strong> ${esc(m.outcome)}</div><div class="bar"><span style="width:${percent(m)}%"></span></div></div>${sectionTabs(m)}<div id="lesson-content">${content}</div></article></div>`;
 }
 function walkthrough(m){
  const step=Math.min(walkSteps[m.id]||0,m.walkthrough.length-1),w=m.walkthrough[step],result=walkOutputs[m.id];
  return `<section class="concept"><div class="eyebrow">FOLLOW THE DATA</div><h2>Build the answer one step at a time</h2><p>${w.sql?'Each step shows a complete runnable query, the result it should produce, and why that changes.':'Each step connects the Excel operation to its inputs, formula or setup, and expected answer. Do the matching steps in Excel using the CSV files.'} The examples use the same records as your labs.</p><div class="walk-step-list" role="group" aria-label="Walkthrough steps">${m.walkthrough.map((s,i)=>`<button class="walk-step ${step===i?'active':''}" data-walk-step="${i}" data-owner="${m.id}" aria-pressed="${step===i}"><span>${i+1}</span>${esc(s.title)}</button>`).join('')}</div><div class="walk-reason"><h3>${esc(w.title)}</h3><p>${esc(w.why)}</p></div><div class="walk-grid"><div><div class="task-label">${w.sql?'WHAT WE ASK THE DATABASE':'EXCEL FORMULA OR SETUP'}</div>${htmlCode(w.sql||w.formula)}<div class="toolbar">${w.sql?`<button class="btn small" data-run-demo="${m.id}">${icon('play')} Run this example</button><button class="textbtn" data-edit-demo="${m.id}">Open an editable copy ↗</button>`:`<button class="btn light small" data-csv="${w.csv}">${icon('down')} Download practice data</button><button class="textbtn" data-page="data">All source files ↗</button>`}</div></div><div><div class="task-label">EXPECTED ANSWER · ${w.rows.length} ${w.rows.length===1?'ROW':'ROWS'}</div>${tableHtml({columns:w.columns,values:w.rows})}<p class="readiness-note">Read the rows, not just the column names. Identify what was kept, added, removed or grouped.</p></div></div><div id="demo-output-${m.id}">${result?.step===step?(result.data.error?`<div class="feedback error">${esc(result.data.error)}</div>`:`<div class="feedback">Live query completed · ${result.data.result.values.length} rows</div>${tableHtml(result.data.result)}`):''}</div><div class="reader-controls"><button class="btn light small" data-walk-step="${Math.max(0,step-1)}" data-owner="${m.id}" ${step===0?'disabled':''}>← Previous step</button><span class="subtle">${step+1} / ${m.walkthrough.length}</span><button class="btn small" data-walk-step="${Math.min(m.walkthrough.length-1,step+1)}" data-owner="${m.id}" ${step===m.walkthrough.length-1?'disabled':''}>Next step →</button></div></section>`;
 }
 function guided(m){const q=window.CAMPUS_GUIDED[m.id];if(!q)return '';const f=guidedFeedback[m.id];return `<section class="concept guided-check"><div class="eyebrow">PREDICT BEFORE YOU CODE</div><h3>${esc(q.q)}</h3>${q.options.map((o,i)=>`<button class="quiz-option ${f?.index===i?(f.pass?'correct':'wrong'):''}" data-guided="${m.id}" data-option="${i}">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}${f?`<div class="feedback ${f.pass?'':'error'}">${f.pass?'Yes. ': 'Revisit the reasoning. '}${esc(q.why)}</div>`:''}<p class="readiness-note">This guided check is for understanding. Your completion percentage is based on the reading checkpoint and the existing graded practice.</p></section>`;}
 function home(){const n=nextModule(),i=modules.indexOf(n),completed=modules.filter(m=>percent(m)===100).length;return `<div class="heading-row"><div><div class="eyebrow">YOUR NEXT CHAPTER</div><h1>From familiar data<br>to confident answers.</h1><p>Your focused SQL & Excel campus for the HAVI technical interview.</p></div><button class="btn light" data-page="reference">${icon('file')} Interview cheat sheet</button></div>${routeTabs()}<section class="hero"><div class="hero-copy"><div class="eyebrow">BUILT FOR YOUR PLANNING SYSTEMS ROLE</div><h2>One clear path.<br>Practice that feels like the job.</h2><p>Investigate demand, connect planning data, catch exceptions, and explain the result. Start where you are.</p><button class="btn lime" data-module="${n.id}">${overall()?'Continue learning':'Start my sprint'} ${icon('arrow')}</button></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><div class="artcard"><small>Planning data · connected</small><div class="artrow"><span>product_id</span><span>forecast</span></div><div class="artrow"><span>P01 · Buns</span><span>110 → 140</span></div><div class="artrow"><span>P02 · Fries</span><span>210 → 250</span></div><div class="artrow"><span>P03 · Cups</span><span>320 → 330</span></div><div style="font-size:10px;margin-top:12px">SELECT clarity FROM practice;</div></div><div class="artpill">✓ LEFT JOIN understood</div></div></section><div class="stats"><div class="stat"><div><div class="value">${overall()}<span style="font-size:16px">%</span></div><p>Route completion</p></div><div class="stat-icon">${icon('chart')}</div></div><div class="stat"><div><div class="value">${completed}<span style="font-size:16px;color:#9da797"> / 10</span></div><p>Modules completed</p></div><div class="stat-icon">${icon('book')}</div></div><div class="stat"><div><div class="value">${formatMinutes(minutes())}</div><p>Suggested total study time</p></div><div class="stat-icon">${icon('clock')}</div></div></div><div class="home-grid"><section><div class="sectionhead"><h2>Your next steps</h2><button class="textbtn" data-page="path">View full path ↗</button></div>${modules.slice(i,Math.min(i+4,modules.length)).map((m,j)=>moduleCard(m,i+j)).join('')}<p class="readiness-note">Completion counts reading confirmations, knowledge checks and passed exercises. Independent SQL passes are tracked separately.</p></section><aside><div class="panel"><div class="eyebrow">FOCUS FOR WEDNESDAY</div><h3>Get the fundamentals right.</h3><div class="focus-list">${['INNER vs LEFT JOIN and complete keys','Find missing data without hiding it','GROUP BY, SUM, COUNT and HAVING','Excel lookups, SUMIFS and PivotTables','Validate totals and explain next actions'].map(t=>`<div class="focus-row">${icon('check')}<span>${t}</span></div>`).join('')}</div></div><div class="panel dark"><div class="eyebrow">YOUR ADVANTAGE</div><h3>You already know the work.</h3><p>Your Excel and Alteryx experience with reconciliations, data flows and exceptions gives you the logic. This course connects that logic to SQL.</p><button class="textbtn" data-page="data">Meet the practice data ↗</button></div></aside></div>`;}
 function path(){return `<div class="heading-row"><div><div class="eyebrow">LEARN IN THIS ORDER</div><h1>Your learning path</h1><p>Work from top to bottom. Every module now teaches the idea, shows the result, then gives you practice.</p></div><span class="badge">${doneUnits()} / ${totalUnits()} activities</span></div>${routeTabs()}<div class="path-note">${routeFast()?'<strong>Your core plan:</strong> about 110 minutes SQL understanding and practice → 30 minutes Excel → 30 minutes rehearsal. Use the times as guides; spend longer on joins if needed.':'<strong>Extra practice:</strong> about 7 hours total, including more queries, receipt summaries and additional Excel checks. Your core progress carries over.'} Follow <strong>Understand → See it happen → Try it yourself</strong> inside each module.</div><div class="home-grid"><section>${modules.map(moduleCard).join('')}</section><aside><div class="panel"><h3>How to use each lesson</h3><p><strong>1. Understand:</strong> one idea at a time, with examples, comparisons and explanations of why it matters.</p><p><strong>2. See it happen:</strong> step through the worked query or Excel example and inspect the changing output.</p><p><strong>3. Try it yourself:</strong> predict the answer, then complete the graded exercises.</p><div class="bar"><span style="width:${overall()}%"></span></div><strong>${overall()}% complete</strong><p class="readiness-note">Completion counts your reading checkpoint, passed knowledge checks and successful labs. Existing progress is retained. Viewing examples alone does not count as an independent lab pass.</p></div><div class="panel dark"><h3>If time gets tight</h3><p>Finish the foundations, filters, joins and aggregation first. Then do the two Excel modules and the rehearsal. Return to more complex multi-step queries afterward.</p><p>Keep advanced database topics and forecasting models for later.</p></div></aside></div>`;}
 function lesson(m){const isMock=m.id==='mock';return `<div class="lesson-layout"><aside class="course-menu"><div class="eyebrow">${routeFast()?'INTERVIEW SPRINT':'FULL PRACTICE'}</div>${modules.map((x,i)=>moduleCard(x,i,true)).join('')}</aside><article class="lesson"><div class="lesson-head"><div class="lesson-meta"><span class="pill ${m.kind==='Excel'?'blue':''}">${esc(m.kind)}</span><span class="muted" style="font-size:11px">Module ${String(modules.indexOf(m)+1).padStart(2,'0')} of 10 · ${m[routeFast()?'fast':'full']} min</span><span class="badge">${percent(m)}% complete</span></div><h1>${esc(m.title)}</h1><p>${esc(m.subtitle)}</p><div class="bar"><span style="width:${percent(m)}%"></span></div></div>${isMock?timerPanel():''}${m.blocks.map(([h,b])=>`<section class="concept"><h3>${esc(h)}</h3>${b}</section>`).join('')}<div class="concept"><label class="checkline"><input type="checkbox" data-read="${m.id}" ${state.lessons[m.id]?'checked':''}>I can explain the main ideas in this lesson in my own words.</label></div>${quiz(m)}<div class="sectionhead"><h2>${isMock?'Practice assessment':'Put it into practice'}</h2><button class="textbtn" data-page="data">Schema & CSV files ↗</button></div>${visibleLabs(m).map(activity).join('')}${visibleLabs(m).length===0?'<div class="path-note">No coding lab in this orientation. The first runnable queries are in the next module.</div>':''}<div class="panel"><h3>My notes</h3><p>Write a useful pattern, a mistake to watch for, or a question to revisit.</p><textarea class="notes" data-note="${m.id}" aria-label="My notes for ${esc(m.title)}" placeholder="For example: A LEFT JOIN keeps the plan rows; check the right key for NULL to find missing mappings.">${esc(state.notes[m.id]||'')}</textarea></div><div class="toolbar"><button class="btn light" data-page="path">Back to path</button><span class="spacer"></span>${modules.indexOf(m)<modules.length-1?`<button class="btn" data-module="${modules[modules.indexOf(m)+1].id}">Next module ${icon('arrow')}</button>`:'<button class="btn" data-page="progress">Review my progress '+icon('arrow')+'</button>'}</div></article></div>`;}
 function quiz(m){const q=m.quiz,f=quizFeedback[m.id],passed=state.quizzes[m.id];return `<section class="activity ${passed?'done':''}"><div class="task-label">Knowledge check ${passed?'· passed':''}</div><h3>${esc(q.q)}</h3>${q.options.map((o,i)=>`<button class="quiz-option ${f?.index===i?(f.pass?'correct':'wrong'):''}" data-quiz="${m.id}" data-option="${i}">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}${f?`<div class="feedback ${f.pass?'':'error'}">${f.pass?'Correct. ': 'Try again. '}${esc(q.why)}</div>`:passed?'<div class="feedback">Passed previously. Try answering again from memory.</div>':''}</section>`;}
 function activity(l){const done=state.labs[l.id],show=solutions[l.id],hintCount=state.hints[l.id]||0;return `<section class="activity ${done?.passed?'done':''}" id="activity-${l.id}"><div class="activity-header"><div><div class="task-label">${isSql(l)?'SQL lab':l.type==='reflection'?'Interview practice':'Excel lab'} ${done?.passed?`· ${done.assisted?'assisted pass':l.type==='reflection'?'self-assessed':'passed'}`:''}</div><h3>${esc(l.title)}</h3></div>${done?.passed?'<span class="badge">✓</span>':''}</div><p>${esc(l.prompt)}</p>${isSql(l)?`<label class="editor-label" for="editor-${l.id}">Your query <span class="kb">Ctrl / ⌘ + Enter</span></label><textarea id="editor-${l.id}" class="sql-editor" spellcheck="false" data-draft="${l.id}" aria-label="SQL query for ${esc(l.title)}">${esc(state.drafts[l.id]??l.starter)}</textarea><div class="toolbar"><button class="btn" data-run="${l.id}">${icon('play')} Run & check</button><button class="btn light small" data-hint="${l.id}">Hint${hintCount?' '+hintCount:''}</button><button class="textbtn" data-solution="${l.id}">${show?'Hide solution':'View solution'}</button><span class="spacer"></span><button class="textbtn" data-retry="${l.id}">Fresh retry</button></div>`:l.type==='answer'?`<label class="editor-label" for="answer-${l.id}">Your Excel result</label><div class="form-row"><input id="answer-${l.id}" class="field" data-draft="${l.id}" value="${esc(state.drafts[l.id]||'')}" placeholder="Enter your answer" autocomplete="off"><button class="btn" data-answer="${l.id}">Check result</button><button class="btn light small" data-hint="${l.id}">Hint</button><button class="textbtn" data-solution="${l.id}">${show?'Hide answer':'View answer'}</button></div><p class="readiness-note">This checks the submitted result, not the formula or workbook steps. Complete the task in Excel before checking.</p>`:`<textarea class="notes" data-draft="${l.id}" aria-label="My interview explanation" placeholder="My evidence, checks and next action...">${esc(state.drafts[l.id]||'')}</textarea><label class="checkline"><input type="checkbox" data-reflect="${l.id}" ${done?.passed?'checked':''}>I rehearsed aloud and covered the scope, evidence, checks and next action.</label><button class="textbtn" data-solution="${l.id}">${show?'Hide example':'See example response'}</button>`}${hintCount?`<div class="hint"><strong>Hint:</strong> ${esc(l.hints[Math.min(hintCount-1,l.hints.length-1)])}</div>`:''}${show?`<div class="hint"><strong>${isSql(l)?'One valid solution':'Worked answer'}</strong>${isSql(l)?htmlCode(l.solution):`<p>${esc(l.solution)}</p>`}<p>${esc(l.explain)}</p></div>`:''}<div class="output" id="output-${l.id}">${outputHtml(outputs[l.id],l)}</div></section>`;}
 function outputHtml(o,l){if(!o)return '';if(o.error)return `<div class="feedback error" role="alert">${esc(friendlyError(o.error))}</div>`;return `${o.check?`<div class="feedback ${o.check.pass?'':'error'}" role="status">${esc(o.check.message)}${o.check.pass&&l?`<br>${esc(l.explain)}`:''}</div>`:''}${o.result?`<div class="result-head"><span>${o.result.values.length} rows · ${o.result.columns.length} columns · ${o.ms??0} ms</span><button class="textbtn" data-export-result="${l?.id||'sandbox'}">Export result CSV</button></div>${tableHtml(o.result)}`:''}`;}
 function friendlyError(e){if(/no such column/i.test(e))return `${e}. Check spelling, table aliases and the schema in Data desk.`;if(/syntax error|incomplete input/i.test(e))return `${e}. Check commas, quotes and whether each clause is complete. Start with SELECT … FROM, then add one condition at a time.`;if(/ambiguous column/i.test(e))return `${e}. Prefix shared column names with the table alias, for example d.product_id.`;return e;}
 function playground(){return `<div class="heading-row"><div><div class="eyebrow">REAL SQL · ZERO SETUP</div><h1>Your SQL playground</h1><p>Experiment freely with the synthetic planning database. Queries run locally in a browser worker.</p></div><button class="btn light" data-page="data">${icon('data')} View schema</button></div><div class="practice-split"><section><div class="panel"><h3>Ask a question. Write a query.</h3><p>Read-only SQLite. SELECT or WITH … SELECT; one statement at a time. SQL Server uses a few different date and row-limit functions.</p><label class="editor-label" for="sandbox">SQL editor <span class="kb">Ctrl / ⌘ + Enter</span></label><textarea id="sandbox" class="sql-editor" style="min-height:260px" aria-label="SQL playground query" spellcheck="false">${esc(sandboxDraft)}</textarea><div class="toolbar"><button class="btn" id="run-sandbox">${icon('play')} Run query</button><button class="btn light" id="reset-sandbox">Reset editor</button></div></div><div class="panel"><h3>Try a starter question</h3>${[['Inspect all planning rows','SELECT * FROM daily_plan LIMIT 10;'],['Find missing actuals','SELECT plan_id, location_id, product_id FROM daily_plan WHERE actual_units IS NULL;'],['Explore stock levels','SELECT * FROM inventory ORDER BY location_id, product_id;']].map(([label,sql])=>`<button class="modulecard" style="padding:12px;margin-bottom:8px" data-starter="${esc(sql)}">${esc(label)} <span class="arrow" style="margin-left:auto">↗</span></button>`).join('')}</div></section><section><div class="panel"><h3>Query results</h3><div id="sandbox-output">${lastSandbox?outputHtml(lastSandbox):'<div class="empty">Run a query to see columns, rows and execution feedback here.</div>'}</div></div><div class="panel dark"><h3>Before trusting the result</h3><div class="focus-list">${['What does each row represent?','Are all key fields included in the join?','Did the join change the row count?','Are missing values separate from zero?','Do the totals match your source control?'].map(x=>`<div class="focus-row">${icon('check')}<span>${x}</span></div>`).join('')}</div></div></section></div>`;}
 function dataPage(){const t=tables[selectedTable];return `<div class="heading-row"><div><div class="eyebrow">YOUR PRACTICE ENVIRONMENT</div><h1>The data desk</h1><p>Small, connected tables for restaurant supply planning. Every record is synthetic.</p></div><button class="btn light" data-page="playground">${icon('code')} Open SQL playground</button></div><div class="path-note"><strong>Relationship map:</strong> daily_plan.product_id → products.product_id; daily_plan.location_id → locations.location_id. Match inventory by date + location + product. Receipts are a many-side table; aggregate before joining. Practice as-of date: November 4, 2026.</div><div class="schema-grid">${Object.entries(tables).map(([name,x])=>`<div class="schema-card"><div class="sectionhead"><h3>${name}</h3><span class="badge">${x.rows.length} rows</span></div><p>${esc(x.grain)}</p><div class="schema-fields">${x.columns.map((c,i)=>`${c} <span class="muted">${esc(x.types[i])}</span>`).join('<br>')}</div><div class="toolbar"><button class="btn light small" data-table="${name}">Preview table</button><button class="textbtn" data-csv="${name}">Download CSV ↓</button></div></div>`).join('')}</div><section class="panel" style="margin-top:22px" id="data-preview"><div class="sectionhead"><h3>${selectedTable}</h3><button class="btn light small" data-csv="${selectedTable}">${icon('down')} CSV for Excel</button></div><p>${esc(t.grain)}</p>${tableHtml({columns:t.columns,values:t.rows})}</section><div class="panel dark"><h3>Intentionally planted issues</h3><p>P99 is absent from the product master. One actual is missing and another is a measured zero. P02 is duplicated in the raw product feed. Some items have multiple receipts. These are practice exceptions to find, explain and validate.</p><p>CSV blanks in actual_units represent SQL NULL. Keep that distinction when calculating forecast error in Excel.</p></div>`;}
 function timerPanel(){return `<div class="panel"><div class="sectionhead"><div><div class="eyebrow">${routeFast()?'30-MINUTE':'60-MINUTE'} REHEARSAL</div><h3>Practice under a little pressure.</h3></div><div class="timer" id="timer">${timeText(state.mock.remaining)}</div></div><div class="toolbar"><button class="btn" id="timer-toggle">${state.mock.running?'Pause':'Start'} timer</button><button class="btn light" id="timer-reset">Reset to ${routeFast()?30:60} minutes</button><span class="muted" style="font-size:11px">The timer continues while this page is open. It pauses when you close or reload the campus.</span></div></div>`;}
 function timeText(n){return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
 function reference(){return `<div class="heading-row"><div><div class="eyebrow">THE PATTERNS TO REMEMBER</div><h1>Quick reference</h1><p>Use while learning. Put it away for a fresh interview rehearsal.</p></div><button class="btn light" id="print">${icon('file')} Print this page</button></div><input class="field full search" id="ref-search" aria-label="Search quick reference" placeholder="Find a pattern: join, NULL, SUMIFS, SQL Server…"><div class="cheat-grid" id="cheat-grid">${window.CAMPUS_CHEATS.map(([h,c,n])=>`<section class="concept cheat" data-search="${esc((h+' '+c+' '+n).toLowerCase())}"><h3>${esc(h)}</h3>${htmlCode(c)}<p>${esc(n)}</p></section>`).join('')}</div><div class="concept"><h3>Questions to clarify before coding</h3><p>What does one row represent? Which reporting period and as-of date? Which table is authoritative? Should unmatched rows be retained? How are NULLs, zero demand and promotions handled? What SQL platform is this? What should the output grain be?</p></div><div class="concept"><h3>Keep your explanation anchored in evidence</h3><p>“I’ll inspect the key uniqueness first, filter the date range, join to the product master, and validate the row count. Then I’ll summarize by the requested grain and check the control total before recommending a next step.”</p></div>`;}
 function progress(){const chosen=modules.flatMap(visibleLabs),sql=chosen.filter(isSql),passed=sql.filter(l=>state.labs[l.id]?.passed),independent=passed.filter(l=>!state.labs[l.id].assisted);return `<div class="heading-row"><div><div class="eyebrow">VISIBLE PROGRESS</div><h1>Every step counts.</h1><p>Your learning history, saved drafts and notes stay in this browser. Export to keep a portable backup.</p></div><button class="btn" id="export-progress">${icon('down')} Export progress</button></div>${routeTabs()}<div class="two-col"><div class="panel"><div class="progress-hero"><svg class="ring" viewBox="0 0 100 100" aria-label="${overall()} percent complete"><circle cx="50" cy="50" r="41" fill="none" stroke="#e8eddf" stroke-width="8"/><circle cx="50" cy="50" r="41" fill="none" stroke="#6b9041" stroke-width="8" stroke-dasharray="${overall()*2.576} 257.6" stroke-linecap="round"/></svg><div><div class="progress-text">${overall()}%</div><strong>${routeFast()?'Interview sprint':'Full route'} completion</strong><p>${doneUnits()} of ${totalUnits()} activities completed</p></div></div><p class="readiness-note">Completion = reading confirmations + passed knowledge checks + successful labs. It does not certify professional SQL proficiency.</p></div><div class="panel"><h3>Your practice evidence</h3><p><strong>${passed.length}/${sql.length}</strong> selected SQL labs passed.<br><strong>${independent.length}</strong> without viewing the solution in the current attempt.<br><strong>${passed.length-independent.length}</strong> assisted passes to retry.</p><p>Excel result checks confirm submitted answers. They do not inspect workbook formulas. Interview explanations are self-assessed.</p>${state.updated?`<p class="subtle">Last saved: ${esc(new Date(state.updated).toLocaleString())}</p>`:''}</div></div>${modules.map(moduleCard).join('')}<div class="two-col"><section class="panel"><h3>Move or back up your progress</h3><p>Export a JSON backup before switching browsers or devices. Importing replaces the progress currently saved in this browser.</p><div class="toolbar"><button class="btn light" id="import-progress">Import backup</button><input type="file" id="import-file" accept="application/json,.json" hidden><button class="textbtn" id="download-notes">Download notes & results</button></div></section><section class="panel"><h3>Start again</h3><p>Reset clears this campus’s saved progress and drafts in this browser. Export first if you want to keep a copy.</p><button class="btn danger" id="reset-progress">Reset my progress</button></section></div>`;}
 function sources(){return `<div class="heading-row"><div><div class="eyebrow">WHY THIS COURSE IS FOCUSED THIS WAY</div><h1>Sources & scope</h1><p>Built for the Planning Systems Specialist role and your confirmed Excel/SQL technical round.</p></div></div><div class="two-col"><section class="panel"><h3>Role-specific priorities</h3><p>The role combines planning-system support with checking inputs, investigating exceptions and reporting results. The posting asks for intermediate SQL and advanced Excel, with data extraction into Excel for analysis.</p><p>That supports a focused curriculum of joins, filters, aggregation, data quality and practical Excel summaries. The mock scenarios are our practice design, not a preview of the employer’s test.</p><p>The next interview is Wednesday, November 11. The round-three correspondence describes a 60-minute technical assessment; the SQL/Excel coverage comes from your interview guidance.</p></section><section class="panel"><h3>Practice assumptions</h3><p>All data are fictional. Restaurant supply scenarios reflect the role context. No HAVI systems, internal data, access details or meeting links are embedded.</p><p>The runnable engine is SQLite via sql.js. HAVI has not confirmed a database dialect or Excel version. Common SQL transfers, while date functions and row limits can vary. Modern Excel is used, with INDEX/MATCH fallback.</p><p>Progress uses local browser storage, with export/import for portability. Your SQL drafts and exercise answers are not sent to a grading server.</p></section></div><section class="panel source-list"><h3>Official references</h3>${window.CAMPUS_SOURCES.map(([label,url,why])=>`${sourceLink(label,url)}<p>${esc(why)}</p>`).join('')}</section>`;}
 function go(p,m){page=p;if(m)selectedModule=m;location.hash=p==='lesson'?`lesson/${selectedModule}`:p;render();window.scrollTo(0,0);}
 function updateOutput(id){const el=document.getElementById(`output-${id}`);if(el)el.innerHTML=outputHtml(outputs[id],findLab(id));bindResultExports();}
 function bindResultExports(){document.querySelectorAll('[data-export-result]').forEach(b=>b.onclick=()=>{const key=b.dataset.exportResult,result=key==='sandbox'?lastSandbox?.result:outputs[key]?.result;if(result)download(`${key}-result.csv`,csv({columns:result.columns,rows:result.values}),'text/csv');});}
 function bind(){
  const refreshLesson=()=>{render();document.querySelector('.lesson-sections')?.scrollIntoView({block:'start'});};
  document.querySelectorAll('[data-lesson-section]').forEach(b=>b.onclick=()=>{lessonSections[b.dataset.owner]=b.dataset.lessonSection;refreshLesson();});
  document.querySelectorAll('[data-read-step]').forEach(b=>b.onclick=()=>{state.readingSteps[b.dataset.owner]=Number(b.dataset.readStep);save();refreshLesson();});
  const picker=document.getElementById('reading-picker');if(picker)picker.onchange=()=>{state.readingSteps[picker.dataset.owner]=Number(picker.value);save();refreshLesson();};
  document.querySelectorAll('[data-walk-step]').forEach(b=>b.onclick=()=>{walkSteps[b.dataset.owner]=Number(b.dataset.walkStep);refreshLesson();});
  document.querySelectorAll('[data-run-demo]').forEach(b=>b.onclick=async()=>{const id=b.dataset.runDemo,m=modules.find(m=>m.id===id),step=walkSteps[id]||0,w=m.walkthrough[step];b.disabled=true;b.textContent='Running…';let data;try{data=await runSql(w.sql);}catch(e){data={error:e.message};}walkOutputs[id]={step,data};const y=window.scrollY;render();window.scrollTo(0,y);});
  document.querySelectorAll('[data-edit-demo]').forEach(b=>b.onclick=()=>{const id=b.dataset.editDemo,m=modules.find(m=>m.id===id);sandboxDraft=m.walkthrough[walkSteps[id]||0].sql;go('playground');});
  document.querySelectorAll('[data-guided]').forEach(b=>b.onclick=()=>{const id=b.dataset.guided,q=window.CAMPUS_GUIDED[id],pass=Number(b.dataset.option)===q.correct;guidedFeedback[id]={index:Number(b.dataset.option),pass};if(pass)state.guided[id]=true;save();const y=window.scrollY;render();window.scrollTo(0,y);});
  document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));
  document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>go('lesson',b.dataset.module));
  document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{const previous=state.route;state.route=b.dataset.route;if(previous!==state.route&&!state.mock.running)state.mock.remaining=routeFast()?1800:3600;save();render();});
  document.querySelectorAll('[data-read]').forEach(b=>b.onchange=()=>{const y=window.scrollY;state.lessons[b.dataset.read]=b.checked;save();render();window.scrollTo(0,y);});
  document.querySelectorAll('[data-quiz]').forEach(b=>b.onclick=()=>{const m=modules.find(m=>m.id===b.dataset.quiz),pass=Number(b.dataset.option)===m.quiz.correct;quizFeedback[m.id]={index:Number(b.dataset.option),pass};if(pass)state.quizzes[m.id]=true;save();const y=window.scrollY;render();window.scrollTo(0,y);});
  document.querySelectorAll('[data-draft]').forEach(el=>{el.oninput=()=>{state.drafts[el.dataset.draft]=el.value;save();};if(el.classList.contains('sql-editor'))el.onkeydown=e=>{if((e.metaKey||e.ctrlKey)&&e.key==='Enter'){e.preventDefault();document.querySelector(`[data-run="${el.dataset.draft}"]`).click();}if(e.key==='Tab'){e.preventDefault();const a=el.selectionStart,z=el.selectionEnd;el.value=el.value.slice(0,a)+'  '+el.value.slice(z);el.selectionStart=el.selectionEnd=a+2;state.drafts[el.dataset.draft]=el.value;save();}};});
  document.querySelectorAll('[data-note]').forEach(el=>el.oninput=()=>{state.notes[el.dataset.note]=el.value;save();});
  document.querySelectorAll('[data-run]').forEach(b=>b.onclick=async()=>{const id=b.dataset.run,l=findLab(id),sql=document.getElementById(`editor-${id}`).value;b.disabled=true;b.innerHTML='Running…';try{const result=await runSql(sql,l.solution,l.ordered);outputs[id]=result;if(result.check.pass){state.labs[id]={passed:true,assisted:!!state.assisted[id],time:new Date().toISOString()};save();toast(state.assisted[id]?'Correct · assisted pass saved. Try a fresh retry later.':'Correct · practice result saved.');}}catch(e){outputs[id]={error:e.message};}b.disabled=false;b.innerHTML=icon('play')+' Run & check';updateOutput(id);if(outputs[id]?.check?.pass){const y=window.scrollY;render();window.scrollTo(0,y);}});
  document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const id=b.dataset.answer,l=findLab(id),raw=document.getElementById(`answer-${id}`).value.trim();const pass=typeof l.answer==='number'?raw!==''&&Number.isFinite(Number(raw.replaceAll(',','').replace('%','')))&&Math.abs(Number(raw.replaceAll(',','').replace('%',''))-l.answer)<=(l.tolerance??.00001):raw.toUpperCase()===l.answer.toUpperCase();outputs[id]={check:{pass,message:pass?'Correct submitted result. '+l.explain:'That result does not match. Check the filters, source ranges, units and blank handling. Use a hint if needed.'}};if(pass)state.labs[id]={passed:true,assisted:!!state.assisted[id],time:new Date().toISOString()};save();const y=window.scrollY;render();window.scrollTo(0,y);});
  document.querySelectorAll('[data-reflect]').forEach(el=>el.onchange=()=>{const id=el.dataset.reflect;if(el.checked&&(state.drafts[id]||'').trim().length<30){el.checked=false;toast('Add a few notes about your findings before marking the rehearsal complete.');return;}state.labs[id]={passed:el.checked,assisted:!!state.assisted[id],selfAssessed:true,time:new Date().toISOString()};save();const y=window.scrollY;render();window.scrollTo(0,y);});
  document.querySelectorAll('[data-hint]').forEach(b=>b.onclick=()=>{const id=b.dataset.hint;state.hints[id]=Math.min((state.hints[id]||0)+1,findLab(id).hints.length);save();const y=window.scrollY;render();window.scrollTo(0,y);});
  document.querySelectorAll('[data-solution]').forEach(b=>b.onclick=()=>{const id=b.dataset.solution;solutions[id]=!solutions[id];if(solutions[id]){state.assisted[id]=true;save();}const y=window.scrollY;render();window.scrollTo(0,y);});
  document.querySelectorAll('[data-retry]').forEach(b=>b.onclick=()=>{const id=b.dataset.retry;state.drafts[id]=findLab(id).starter;state.assisted[id]=false;state.hints[id]=0;delete state.labs[id];delete outputs[id];solutions[id]=false;save();const y=window.scrollY;render();window.scrollTo(0,y);});
  document.querySelectorAll('[data-csv]').forEach(b=>b.onclick=()=>download(`${b.dataset.csv}.csv`,csv(tables[b.dataset.csv]),'text/csv'));
  document.querySelectorAll('[data-table]').forEach(b=>b.onclick=()=>{selectedTable=b.dataset.table;render();document.getElementById('data-preview').scrollIntoView({block:'start'});});
  document.querySelectorAll('[data-starter]').forEach(b=>b.onclick=()=>{sandboxDraft=b.dataset.starter;render();});
  const sb=document.getElementById('sandbox');if(sb){sb.oninput=()=>sandboxDraft=sb.value;sb.onkeydown=e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();document.getElementById('run-sandbox').click();}};}
  const run=document.getElementById('run-sandbox');if(run)run.onclick=async()=>{run.disabled=true;run.textContent='Running…';try{lastSandbox=await runSql(sandboxDraft);}catch(e){lastSandbox={error:e.message};}run.disabled=false;run.innerHTML=icon('play')+' Run query';document.getElementById('sandbox-output').innerHTML=outputHtml(lastSandbox);bindResultExports();};
  const rs=document.getElementById('reset-sandbox');if(rs)rs.onclick=()=>{sandboxDraft='SELECT *\nFROM daily_plan\nLIMIT 10;';lastSandbox=null;render();};
  const tt=document.getElementById('timer-toggle');if(tt)tt.onclick=()=>{state.mock.running=!state.mock.running;save();render();};
  const tr=document.getElementById('timer-reset');if(tr)tr.onclick=()=>{state.mock={remaining:routeFast()?1800:3600,running:false};save();render();};
  const ep=document.getElementById('export-progress');if(ep)ep.onclick=()=>download('planning-lab-progress.json',JSON.stringify(state,null,2),'application/json');
  const ip=document.getElementById('import-progress');if(ip)ip.onclick=()=>document.getElementById('import-file').click();
  const fi=document.getElementById('import-file');if(fi)fi.onchange=async()=>{try{const file=fi.files[0];if(!file)return;if(file.size>2e6)throw new Error('This file is too large for a progress backup.');const d=JSON.parse(await file.text());if(d.version!==1||!['sprint','full'].includes(d.route)||!d.lessons||!d.labs||!d.drafts)throw new Error('Choose a Planning Lab progress backup.');if(!confirm('Replace the progress currently saved in this browser with this backup?'))return;state={...emptyState(),...d,mock:{...emptyState().mock,...d.mock,running:false}};save();render();toast('Progress restored.');}catch(e){toast(e.message);}};
  const rp=document.getElementById('reset-progress');if(rp)rp.onclick=()=>{if(confirm('Clear all Planning Lab progress, notes and drafts in this browser? Export first if you need a backup.')){state=emptyState();outputs={};solutions={};quizFeedback={};save();render();toast('Progress reset.');}};
  const dn=document.getElementById('download-notes');if(dn)dn.onclick=()=>{let text=`PLANNING LAB — STUDY NOTES\nRoute: ${state.route}\nCompletion: ${overall()}%\n\n`;for(const m of modules){text+=`${m.title}\n${state.notes[m.id]||'(No notes)'}\n`;for(const l of m.labs){if(state.labs[l.id]?.passed)text+=`Passed: ${l.title} (${state.labs[l.id].assisted?'assisted':'without viewing solution in current attempt'})\n`;}text+='\n';}download('planning-lab-study-notes.txt',text);};
  const print=document.getElementById('print');if(print)print.onclick=()=>window.print();
  const search=document.getElementById('ref-search');if(search)search.oninput=()=>document.querySelectorAll('.cheat').forEach(el=>el.hidden=!el.dataset.search.includes(search.value.toLowerCase()));
  bindResultExports();
 }
 setInterval(()=>{if(state.mock.running&&state.mock.remaining>0){state.mock.remaining--;if(state.mock.remaining===0){state.mock.running=false;toast('Rehearsal time is up. Review what you completed and explain your approach.');}save();const el=document.getElementById('timer');if(el)el.textContent=timeText(state.mock.remaining);if(state.mock.remaining===0)render();}},1000);
 function loadHash(){const hash=location.hash.slice(1),parts=hash.split('/');if(parts[0]==='lesson'&&modules.some(m=>m.id===parts[1])){page='lesson';selectedModule=parts[1];}else if(['home','path','playground','data','mock','reference','progress','sources'].includes(hash))page=hash;}
 window.addEventListener('hashchange',()=>{loadHash();render();});
 initWorker();loadHash();render();
})();
